import * as React from 'react'
import { Box, LinkBox, LinkOverlay, LinkBoxProps, LinkOverlayProps } from '@chakra-ui/react'
import { vars } from '@theme'
import { Ripples } from '@atoms'

import * as Type from '../types'
import { isCourseActive } from '../utils'

interface ImageBoxProps {
  backgroundImg: string
  title: string
  data?: Type.ExtendAcademicList
  size?: 'large' | 'small'
  m?: string
}

// Componente que agrega efecto al hacer click
interface WithRipplesProps {
  enabled: boolean
  children: React.ReactNode
}

const StyledLinkBox = LinkBox as React.FC<LinkBoxProps>
const StyledLinkOverlay = LinkOverlay as React.FC<LinkOverlayProps>

function WithRipples({ enabled, children }: WithRipplesProps): JSX.Element {
  return enabled ? <Ripples>{children}</Ripples> : <>{children}</>
}

export function BoxImage({
  backgroundImg,
  title,
  data,
  size = 'large',
  m,
}: ImageBoxProps): JSX.Element {
  const hasCustomClick = data?.onClick !== undefined
  const isClickable =
    hasCustomClick || isCourseActive(data?.action?.enabled ?? false, data?.Profile?.id)
  const hasHref = !hasCustomClick && !!data?.action?.href

  const handleClick = (event: React.MouseEvent<HTMLElement>): void => {
    event.preventDefault()
    data?.onClick?.(data)
  }

  const handleKeyDown = (event: React.KeyboardEvent<HTMLElement>): void => {
    if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault()
      data?.onClick?.(data)
    }
  }

  const boxHeight = {
    large: '286px',
    small: '197px',
  }
  return (
    <WithRipples enabled={isClickable}>
      <StyledLinkBox
        className="CourseList-ImageBox"
        _focusVisible={{
          boxShadow: `0 0 0 3px ${vars('colors-alert-deepSkyBlue')} inset`,
        }}
        tabIndex={0}
        sx={{
          backgroundImage: `linear-gradient(to bottom, rgba(0,0,0,0) 35%, rgba(0,0,0,1) 100%), url(${backgroundImg})`,
          color: vars('colors-neutral-white'),
          cursor: 'pointer',
          height: boxHeight[size], // Customize the height based on the type prop
          backgroundSize: 'cover',
          backgroundPosition: 'center',
          borderRadius: '10px',
          padding: '16px',
          display: 'flex',
          font: 'Roboto',
          flexDirection: 'column',
          margin: m,
          justifyContent: 'end',
          textAlign: 'left',

          a: {
            '&:active': {
              boxShadow: 'none',
            },
          },
        }}
        aria-label={hasCustomClick ? title : undefined}
        role={hasCustomClick ? 'button' : undefined}
        onKeyDown={hasCustomClick ? handleKeyDown : undefined}
      >
        {(hasCustomClick || !data?.hasFinanzeFreezed) &&
          isClickable &&
          (hasHref || hasCustomClick) && (
            <StyledLinkOverlay
              data-testid="course-link-overlay"
              href={hasHref ? data?.action?.href : undefined}
              isExternal={hasHref && data?.action?.targetBlank}
              onClick={hasCustomClick ? handleClick : undefined}
              tabIndex={-1}
            />
          )}

        <Box className="textBox" bottom="20px" display="flex" flexDirection="column" gap="8px">
          <Box
            as="h2"
            className="courseName"
            fontWeight="700"
            fontSize="16px"
            lineHeight="21px"
            marginBlockEnd="0"
            margin="0"
          >
            {title}
          </Box>

          {data?.information?.map(
            (item, index) =>
              item.icon === 'certificate' && (
                <Box
                  as="p"
                  className="certificateText"
                  fontSize="14px"
                  fontWeight="400"
                  lineHeight="12px"
                  margin="0"
                  key={index}
                >
                  {item.text}
                </Box>
              )
          )}
        </Box>
      </StyledLinkBox>
    </WithRipples>
  )
}

BoxImage.displayName = 'BoxImage'
